//@ProcessingGroup("dSP")
@Component("dSP-projector")
public class DSPProjector extends DSPEntityProjector {
		
	// core constructor
	public DSPProjector(ProjectorRegistry registry,
									DSPRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateDSPEvent
     */
    @EventHandler( payloadType=CreateDSPEvent.class )
    public void handle( CreateDSPEvent event) {
	    LOGGER.info("handling CreateDSPEvent - " + event );
	    DSP entity = new DSP();
            entity.setDSPId( event.getDSPId() );
            entity.setName( event.getName() );
            entity.setWebsite( event.getWebsite() );
            entity.setRegion( event.getRegion() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDSP( entity );
    }

    /*
     * @param	event UpdateDSPEvent
     */
    @EventHandler( payloadType=UpdateDSPEvent.class )
    public void handle( UpdateDSPEvent event) {
    	LOGGER.info("handling UpdateDSPEvent - " + event );
    	
	    DSP entity = new DSP();
            entity.setDSPId( event.getDSPId() );
            entity.setName( event.getName() );
            entity.setWebsite( event.getWebsite() );
            entity.setRegion( event.getRegion() );
            entity.setAdAccounts( event.getAdAccounts() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindDSP( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDSP( entity );        
    }
    
    /*
     * @param	event DeleteDSPEvent
     */
    @EventHandler( payloadType=DeleteDSPEvent.class )
    public void handle( DeleteDSPEvent event) {
    	LOGGER.info("handling DeleteDSPEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	DSP entity = delete( event.getDSPId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDSP( entity );

    }    


    /*
     * @param	event AssignAdAccountsToDSPEvent
     */
    @EventHandler( payloadType=AssignAdAccountsToDSPEvent.class)
    public void handle( AssignAdAccountsToDSPEvent event) {
	    LOGGER.info("handling AssignAdAccountsToDSPEvent - " + event );
	    
	    // ------------------------------------------
    	// delegate to addTo 
    	// ------------------------------------------ 
	    DSP entity = addToAdAccounts(event.getDSPId(), event.getAddTo() );
        
    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindDSP( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDSP( entity );
    }
    

/*
 * @param	event RemoveAdAccountsFromDSPEvent
 */
@EventHandler( payloadType=RemoveAdAccountsFromDSPEvent.class)
public void handle( RemoveAdAccountsFromDSPEvent event) {
    LOGGER.info("handling RemoveAdAccountsFromDSPEvent - " + event );

    DSP entity = removeFromAdAccounts(event.getDSPId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindDSP( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllDSP( entity );
}



    /**
     * Method to retrieve the DSP via an DSPPrimaryKey.
     * @param 	id Long
     * @return 	DSP
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public DSP handle( FindDSPQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getDSPId() );
    }
    
    /**
     * Method to retrieve a collection of all DSPs
     *
     * @param	query	FindAllDSPQuery 
     * @return 	List<DSP> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<DSP> handle( FindAllDSPQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindDSP,
 * but only if the id matches
 *
 * @param		entity	DSP
 */
	protected void emitFindDSP( DSP entity ) {
		LOGGER.info("handling emitFindDSP" );
		
	    queryUpdateEmitter.emit(FindDSPQuery.class,
	                            query -> query.getFilter().getDSPId().equals(entity.getDSPId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDSP
	 * 
	 * @param		entity	DSP
	 */
	protected void emitFindAllDSP( DSP entity ) {
		LOGGER.info("handling emitFindAllDSP" );
		
	    queryUpdateEmitter.emit(FindAllDSPQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(DSPProjector.class.getName());

}
